// Malyavan, the old counsellor: a pale leather puppet with a white beard on the jaw, a tall crown and a staff. Drawn facing left.
Object.assign(W, {
  malyavan(cls) {
    const O = W.O, back = 'color-mix(in srgb, var(--skinE) 76%, var(--ink))';
    let strands = '';
    for (let i = 0; i < 6; i++) strands += 'M' + (-70 + i * 14) + ' -690 Q' + (-80 + i * 12) + ' -630 ' + (-58 + i * 9) + ' -575 ';
    return '<g class="' + cls + '">' +
      '<path d="M96 -330 L140 900" style="stroke:var(--ink);stroke-width:4"/>' +
      '<path d="M30 -808 Q112 -770 102 -686 Q124 -604 98 -540 Q80 -572 66 -622 Q46 -692 18 -716 Z" style="fill:var(--second);' + O + '"/>' +
      '<path d="M40 -612 L76 -600 L98 -462 L66 -456 Z M66 -470 L96 -466 L112 -342 L84 -338 Z" style="fill:' + back + ';' + O + '"/><circle cx="98" cy="-326" r="17" style="fill:' + back + ';' + O + '"/>' +
      '<path d="M-90 -392 L90 -392 L104 -14 L-110 -14 Z" style="fill:var(--redDeep);' + O + '"/><path d="M-108 -60 L102 -60 L104 -14 L-110 -14 Z" style="fill:var(--gold);' + O + '"/>' + W.lace(-100, -37, 96, -37, 14, 4) +
      '<path d="M-90 -14 L-30 -14 L-24 0 L-112 0 Z M20 -14 L70 -14 L84 0 L10 0 Z" style="fill:var(--goldDeep);' + O + '"/>' +
      '<path d="M-82 -632 Q-98 -520 -88 -392 L92 -392 Q102 -520 72 -632 Z" style="fill:var(--goldDeep);' + O + '"/>' +
      '<path d="M66 -628 L96 -600 L-70 -400 L-90 -430 Z" style="fill:var(--red);' + O + '"/>' + W.lace(76, -606, -74, -420, 12, 3.5) +
      '<path d="M-44 -676 L22 -676 L32 -628 L-48 -628 Z" style="fill:var(--skinE);' + O + '"/>' +
      '<g class="' + cls + '-head">' +
      '<path d="M54 -812 Q-30 -832 -66 -798 L-74 -758 L-100 -735 Q-94 -724 -82 -722 L-76 -712 Q-40 -699 0 -690 L42 -700 Q76 -745 54 -812 Z" style="fill:var(--skinE);' + O + '"/>' +
      '<path d="M-12 -760 Q4 -742 -4 -724 M10 -790 Q24 -770 18 -748" style="fill:none;stroke:var(--goldDeep);stroke-width:2.5"/>' +
      '<g class="' + cls + '-jaw"><path d="M-76 -712 Q-85 -700 -79 -690 Q-83 -676 -70 -667 Q-40 -658 -4 -672 L22 -700 Q-30 -699 -76 -712 Z" style="fill:var(--skinE);' + O + '"/>' +
      '<path d="M-82 -702 Q-100 -640 -72 -560 Q-50 -515 -30 -560 Q-8 -604 12 -646 L24 -700 Q-30 -688 -82 -702 Z" style="fill:var(--second);' + O + '"/><path d="' + strands + '" style="fill:none;stroke:var(--cloth);stroke-width:2.5"/></g>' +
      '<path d="M-92 -716 Q-60 -738 -18 -716 Q12 -700 22 -656 Q4 -688 -24 -703 Q-56 -716 -92 -716 Z" style="fill:var(--second);' + O + '"/>' +
      '<path d="M-68 -752 Q-48 -764 -26 -754 Q-48 -746 -68 -752 Z" style="fill:var(--second);' + O + '"/><circle cx="-46" cy="-752" r="5" style="fill:var(--ink)"/><path d="M-70 -754 Q-48 -766 -22 -756" style="fill:none;stroke:var(--ink);stroke-width:4"/>' +
      '<path d="M-82 -770 Q-50 -796 -6 -776 Q-42 -782 -82 -764 Z" style="fill:var(--second);' + O + '"/>' +
      '<path d="M-44 -806 V-788" style="stroke:var(--red);stroke-width:5;stroke-linecap:round"/>' +
      '<circle cx="26" cy="-706" r="16" style="fill:none;stroke:var(--gold);stroke-width:7"/>' +
      '<path d="M-70 -808 L62 -818 L64 -846 L-66 -838 Z" style="fill:var(--gold);' + O + '"/>' + W.lace(-56, -825, 52, -833, 9, 4) +
      '<path d="M-54 -840 L52 -846 L34 -930 L-36 -926 Z" style="fill:var(--second);' + O + '"/>' + W.lace(-40, -880, 40, -884, 6, 4) +
      '<path d="M-36 -928 L34 -932 L-1 -1030 Z" style="fill:var(--gold);' + O + '"/><circle cx="-1" cy="-1036" r="10" style="fill:var(--red);' + O + '"/><circle cx="-1" cy="-962" r="11" style="fill:var(--red);' + O + '"/></g>' +
      '<g class="' + cls + '-arm"><path d="M-196 -790 L-196 40" style="stroke:var(--goldDeep);stroke-width:12;stroke-linecap:round"/><circle cx="-196" cy="-800" r="18" style="fill:var(--gold);' + O + '"/>' +
      '<path d="M-82 -618 L-46 -598 L-104 -484 L-134 -500 Z M-134 -500 L-104 -484 L-182 -462 L-192 -490 Z" style="fill:var(--skinE);' + O + '"/>' +
      '<path d="M-186 -500 Q-214 -500 -214 -474 Q-206 -456 -182 -458 Z" style="fill:var(--skinE);' + O + '"/><ellipse cx="-66" cy="-612" rx="30" ry="20" style="fill:var(--red);' + O + '"/></g>' +
      '</g>';
  },
});
W.RIG.malyavan = { jaw: [-10, -705], arm: [-60, -605] };

kit.scene('elder', {
  init(kit) {
    this.s = W.shot(kit, {
      id: 'elder', back: '<rect width="918" height="1027" style="fill:var(--accent);opacity:.16"/><g style="opacity:.25">' + W.lace(60, 140, 60, 960, 16, 8) + '</g>',
      cast: [{ who: 'malyavan', x: 380, y: 1760, s: 1.4, flip: true }],
      cam: [1.0, 1.05, 465, 515, 472, 500],
      arm: (t, i, talk) => (talk ? 4 + 3 * Math.sin(t * 1.3) : 2 * Math.sin(t * 0.6)),
      lines: [[57.3, 58.9, 'लंकेश, बीते वीरों का शोक है तुम्हें…', 0, 0], [59.4, 60.4, 'पर लंका की प्रजा', 0, 0], [60.8, 62.5, 'जो अभी जीवित है,', 0, 0], [62.8, 64.2, 'उसकी चिंता कौन करेगा?', 0, 0]],
    });
  },
  render(t) { this.s.render(t); },
});
